-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

SET allow_experimental_variant_type = 1;
SET allow_suspicious_variant_types = 1;

-- A BOOLEAN union branch must accept an Enum8 alternative as its hint, the same conversion the
-- ordinary (non-union) ORC path supports through the final cast. Otherwise the boolean arm is
-- left unhinted, reads back as Bool, and the final Variant -> Variant cast is rejected because
-- Enum8(...) is not an extension of Bool.

-- union<boolean, string> read as Variant(Enum8('false' = 0, 'true' = 1), String).
-- Rows: true, 'x', false.
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(Enum8(''false'' = 0, ''true'' = 1), String)', unhex('')) ORDER BY toString(u);

-- union<boolean, tinyint> read as Variant(Enum8('false' = 0, 'true' = 1), Int8): Enum8 matches
-- only the boolean branch, so singles-elimination assigns it there and the tinyint branch takes
-- Int8. Rows: true, 5, false, -6, NULL (a null payload in the boolean branch).
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(Enum8(''false'' = 0, ''true'' = 1), Int8)', unhex('')) ORDER BY toString(u);
